    thumbnailPath: thumbnail
  })
  .then(res => {
    console.log('\n======================================================');
    console.log('?? TRANSMISI?N PROGRAMADA CON ?XITO');
    console.log('======================================================');
    console.log(JSON.stringify(res, null, 2));
  })
  .catch(err => {
    console.error('? Error al crear la emisi?n:', err.message);
  });
}

import { google } from 'googleapis';
